1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  :root {
9	    --bg: #111418;
10	    --panel: #1b2027;
11	    --grid: #232a33;
12	    --text: #e8ecf1;
13	    --muted: #8b96a5;
14	    --I: #22c7e8;
15	    --O: #f2c613;
16	    --T: #a64ee0;
17	    --S: #3fc15a;
18	    --Z: #e8453c;
19	    --J: #3a6fe8;
20	    --L: #f08a24;
21	  }
22	  * { box-sizing: border-box; }
23	  body {
24	    margin: 0;
25	    min-height: 100vh;
26	    background: var(--bg);
27	    color: var(--text);
28	    font: 15px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
29	    display: flex;
30	    align-items: center;
31	    justify-content: center;
32	    padding: 16px;
33	  }
34	  .game { display: flex; gap: 20px; align-items: flex-start; flex-wrap: wrap; justify-content: center; }
35	  .board {
36	    display: grid;
37	    grid-template-columns: repeat(10, 28px);
38	    grid-template-rows: repeat(20, 28px);
39	    gap: 1px;
40	    background: var(--grid);
41	    border: 2px solid var(--grid);
42	    border-radius: 4px;
43	  }
44	  .cell { background: var(--bg); }
45	  .side { display: flex; flex-direction: column; gap: 12px; min-width: 140px; }
46	  .box { background: var(--panel); border-radius: 6px; padding: 10px 12px; }
47	  .label { color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: .08em; }
48	  .value { font-size: 22px; font-weight: 600; font-variant-numeric: tabular-nums; }
49	  .preview {
50	    display: grid;
51	    grid-template-columns: repeat(4, 20px);
52	    grid-template-rows: repeat(2, 20px);
53	    gap: 1px;
54	    margin-top: 6px;
55	  }
56	  .preview div { background: transparent; }
57	  .p-I { background: var(--I) !important; }
58	  .p-O { background: var(--O) !important; }
59	  .p-T { background: var(--T) !important; }
60	  .p-S { background: var(--S) !important; }
61	  .p-Z { background: var(--Z) !important; }
62	  .p-J { background: var(--J) !important; }
63	  .p-L { background: var(--L) !important; }
64	  button {
65	    background: var(--panel); color: var(--text); border: 1px solid var(--grid);
66	    border-radius: 6px; padding: 8px 12px; font: inherit; cursor: pointer;
67	  }
68	  button:hover { border-color: var(--muted); }
69	  .keys { color: var(--muted); font-size: 13px; }
70	</style>
71	</head>
72	<body>
73	<div class="game">
74	  <div class="board" data-testid="board" id="board"></div>
75	  <div class="side">
76	    <div class="box"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
77	    <div class="box"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
78	    <div class="box"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
79	    <div class="box"><div class="label">Next</div><div class="preview" id="preview"></div></div>
80	    <button id="restart" type="button">New game</button>
81	    <div class="keys">← → move<br>↑ rotate<br>↓ soft drop<br>Space hard drop</div>
82	  </div>
83	</div>
84	<script>
85	(function () {
86	  "use strict";
87	
88	  var ROWS = 20, COLS = 10;
89	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
90	
91	  // Spawn shapes as [row, col] offsets from the piece origin.
92	  var SHAPES = {
93	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
94	    O: [[0, 1], [0, 2], [1, 1], [1, 2]],
95	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
96	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
97	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
98	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
99	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
100	  };
101	  // Side length of the square each shape rotates within.
102	  var BOX = { I: 4, O: 2, T: 3, S: 3, Z: 3, J: 3, L: 3 };
103	  var SPAWN_COL = 3;
104	  var GRAVITY_MS = 1000;
105	
106	  // Locking rule (project decision): a gravity step that cannot move the piece
107	  // down counts one lock tick; the piece locks on the LOCK_TICKS-th tick.
108	  // Left/right while resting restarts the delay, at most MAX_LOCK_RESETS times
109	  // per piece. Hard drop locks at once.
110	  var LOCK_TICKS = 2;
111	  var MAX_LOCK_RESETS = 3;
112	  // Rotation tries these sideways shifts, in order, until one fits.
113	  var KICKS = [0, -1, 1, -2, 2];
114	
115	  // Scoring rule (project decision): a clear scores CLEAR_POINTS[rows] x level.
116	  // Clearing rows together must always beat clearing them one at a time.
117	  // Soft drop scores 1 per cell moved by the player (gravity scores nothing);
118	  // hard drop scores 2 per cell dropped. Drop points are not multiplied.
119	  var CLEAR_POINTS = [0, 100, 300, 500, 800];
120	  var SOFT_DROP_POINTS = 1;
121	  var HARD_DROP_POINTS = 2;
122	
123	  var state = {
124	    board: [],      // ROWS x COLS, "" or piece letter
125	    current: null,  // { type, row, col, shape, lockTicks, lockResets }
126	    next: [],
127	    score: 0,
128	    level: 1,
129	    lines: 0,
130	    status: "running"
131	  };
132	
133	  // ---- core logic ----
134	
135	  function emptyBoard() {
136	    var b = [];
137	    for (var r = 0; r < ROWS; r++) {
138	      var row = [];
139	      for (var c = 0; c < COLS; c++) row.push("");
140	      b.push(row);
141	    }
142	    return b;
143	  }
144	
145	  function randomType() {
146	    return TYPES[Math.floor(Math.random() * TYPES.length)];
147	  }
148	
149	  function cellsOf(piece, dRow, dCol) {
150	    return piece.shape.map(function (o) {
151	      return [piece.row + (dRow || 0) + o[0], piece.col + (dCol || 0) + o[1]];
152	    });
153	  }
154	
155	  function fits(piece, dRow, dCol) {
156	    return cellsOf(piece, dRow, dCol).every(function (p) {
157	      return p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS && state.board[p[0]][p[1]] === "";
158	    });
159	  }
160	
161	  function spawn() {
162	    var type = state.next.length ? state.next.shift() : randomType();
163	    if (!state.next.length) state.next.push(randomType());
164	    state.current = { type: type, row: 0, col: SPAWN_COL, shape: SHAPES[type], lockTicks: 0, lockResets: 0 };
165	  }
166	
167	  function lock() {
168	    var piece = state.current;
169	    cellsOf(piece).forEach(function (p) { state.board[p[0]][p[1]] = piece.type; });
170	    state.current = null;
171	    clearLines();
172	    spawn();
173	  }
174	
175	  // Remove every full row; rows above drop down. Scores the clear.
176	  function clearLines() {
177	    var kept = state.board.filter(function (row) {
178	      return row.some(function (t) { return t === ""; });
179	    });
180	    var cleared = ROWS - kept.length;
181	    if (!cleared) return;
182	    while (kept.length < ROWS) kept.unshift(emptyBoard()[0]);
183	    state.board = kept;
184	    state.lines += cleared;
185	    state.score += CLEAR_POINTS[cleared] * state.level;
186	  }
187	
188	  function tryMove(dRow, dCol) {
189	    if (!state.current || !fits(state.current, dRow, dCol)) return false;
190	    state.current.row += dRow;
191	    state.current.col += dCol;
192	    if (dRow > 0) state.current.lockTicks = 0;
193	    return true;
194	  }
195	
196	  // Sideways move. If the lock delay is running, restart it (capped per piece).
197	  function shift(dCol) {
198	    var piece = state.current;
199	    if (!tryMove(0, dCol)) return;
200	    if (piece.lockTicks > 0 && piece.lockResets < MAX_LOCK_RESETS) {
201	      piece.lockResets++;
202	      piece.lockTicks = 0;
203	    }
204	  }
205	
206	  function rotateCW() {
207	    var piece = state.current;
208	    if (!piece || piece.type === "O") return;
209	    var n = BOX[piece.type];
210	    var turned = {
211	      type: piece.type, row: piece.row, col: piece.col,
212	      shape: piece.shape.map(function (o) { return [o[1], n - 1 - o[0]]; })
213	    };
214	    for (var i = 0; i < KICKS.length; i++) {
215	      if (fits(turned, 0, KICKS[i])) {
216	        piece.shape = turned.shape;
217	        piece.col += KICKS[i];
218	        return;
219	      }
220	    }
221	  }
222	
223	  // One gravity step. The timer and __tetris.tick both call this.
224	  function gravityStep() {
225	    if (state.status !== "running" || !state.current) return;
226	    if (tryMove(1, 0)) return;
227	    state.current.lockTicks++;
228	    if (state.current.lockTicks >= LOCK_TICKS) lock();
229	  }
230	
231	  var actions = {
232	    left: function () { if (state.current) shift(-1); },
233	    right: function () { if (state.current) shift(1); },
234	    rotateCW: rotateCW,
235	    softDrop: function () {
236	      if (tryMove(1, 0)) state.score += SOFT_DROP_POINTS;
237	    },
238	    hardDrop: function () {
239	      if (!state.current) return;
240	      while (tryMove(1, 0)) state.score += HARD_DROP_POINTS;
241	      lock();
242	    }
243	  };
244	
245	  function doAction(name) {
246	    if (state.status !== "running" || !actions[name]) return;
247	    actions[name]();
248	    render();
249	  }
250	
251	  function newGame(queue) {
252	    state.board = emptyBoard();
253	    state.score = 0;
254	    state.level = 1;
255	    state.lines = 0;
256	    state.status = "running";
257	    state.next = Array.isArray(queue) ? queue.slice() : [];
258	    spawn();
259	    restartTimer();
260	    render();
261	  }
262	
263	  // ---- rendering (synchronous) ----
264	
265	  var boardEl = document.getElementById("board");
266	  var previewEl = document.getElementById("preview");
267	  var scoreEl = document.getElementById("score");
268	  var levelEl = document.getElementById("level");
269	  var linesEl = document.getElementById("lines");
270	  var cellEls = [];
271	  var previewEls = [];
272	
273	  (function buildDom() {
274	    for (var r = 0; r < ROWS; r++) {
275	      var row = [];
276	      for (var c = 0; c < COLS; c++) {
277	        var el = document.createElement("div");
278	        el.className = "cell";
279	        el.setAttribute("data-testid", "cell");
280	        el.setAttribute("data-row", String(r));
281	        el.setAttribute("data-col", String(c));
282	        el.setAttribute("data-filled", "false");
283	        el.setAttribute("data-piece", "");
284	        boardEl.appendChild(el);
285	        row.push(el);
286	      }
287	      cellEls.push(row);
288	    }
289	    for (var i = 0; i < 8; i++) {
290	      var p = document.createElement("div");
291	      previewEl.appendChild(p);
292	      previewEls.push(p);
293	    }
294	  })();
295	
296	  function paint(el, type) {
297	    el.className = el.className.replace(/\s*p-[A-Z]/g, "") + (type ? " p-" + type : "");
298	  }
299	
300	  function render() {
301	    var view = state.board.map(function (row) { return row.slice(); });
302	    if (state.current) {
303	      cellsOf(state.current).forEach(function (p) {
304	        if (p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS) view[p[0]][p[1]] = state.current.type;
305	      });
306	    }
307	    for (var r = 0; r < ROWS; r++) {
308	      for (var c = 0; c < COLS; c++) {
309	        var el = cellEls[r][c], t = view[r][c];
310	        el.setAttribute("data-filled", t ? "true" : "false");
311	        el.setAttribute("data-piece", t);
312	        paint(el, t);
313	      }
314	    }
315	    previewEls.forEach(function (el) { paint(el, ""); });
316	    var nextType = state.next[0];
317	    if (nextType) {
318	      SHAPES[nextType].forEach(function (o) { paint(previewEls[o[0] * 4 + o[1]], nextType); });
319	    }
320	    scoreEl.textContent = String(state.score);
321	    levelEl.textContent = String(state.level);
322	    linesEl.textContent = String(state.lines);
323	  }
324	
325	  // ---- timer ----
326	
327	  var timer = null;
328	  function onTimer() { gravityStep(); render(); }
329	  function restartTimer() {
330	    if (timer) clearInterval(timer);
331	    timer = setInterval(onTimer, GRAVITY_MS);
332	  }
333	
334	  // ---- input ----
335	
336	  var KEYS = { ArrowLeft: "left", ArrowRight: "right", ArrowDown: "softDrop", ArrowUp: "rotateCW", " ": "hardDrop" };
337	  document.addEventListener("keydown", function (e) {
338	    var action = KEYS[e.key];
339	    if (!action) return;
340	    e.preventDefault();
341	    doAction(action);
342	  });
343	  document.getElementById("restart").addEventListener("click", function (e) {
344	    e.currentTarget.blur();
345	    newGame();
346	  });
347	
348	  // ---- test control surface ----
349	
350	  window.__tetris = {
351	    newGame: function (queue) { newGame(queue); },
352	    setQueue: function (queue) {
353	      state.next = Array.isArray(queue) ? queue.slice() : [];
354	      render();
355	    },
356	    setBoard: function (rows) {
357	      state.board = rows.map(function (line) {
358	        return line.split("").map(function (ch) { return ch === "." ? "" : ch; });
359	      });
360	      render();
361	    },
362	    tick: function (n) {
363	      var steps = n === undefined ? 1 : n;
364	      for (var i = 0; i < steps; i++) gravityStep();
365	      render();
366	    },
367	    input: function (action) { doAction(action); },
368	    getBoard: function () {
369	      return state.board.map(function (row) {
370	        return row.map(function (t) { return t || "."; }).join("");
371	      });
372	    },
373	    getState: function () {
374	      return {
375	        current: state.current
376	          ? { type: state.current.type, cells: cellsOf(state.current) }
377	          : null,
378	        next: state.next.slice(),
379	        score: state.score,
380	        level: state.level,
381	        lines: state.lines,
382	        status: state.status
383	      };
384	    }
385	  };
386	
387	  newGame();
388	})();
389	</script>
390	</body>
391	</html>
